INSERT INTO `atendimentos` VALUES (1,3,15,22,'Dor no peito ao esforço','Paciente relata dor precordial há 3 semanas, desencadeada por esforço físico, sem irradiação.','Ausculta pulmonar limpa. Ritmo cardíaco regular, 2T, sem sopros.','130/85',78,36.5,98,72.50,168,'Angina estável - investigar','RLU9PBaUfEUEI5x/edcfAw8htGN+XvSNcwMS28KfjKSWUnq7Qcxs2R1LGP/TDwJNjHeO5wgxceg=','I20.8','Solicitado eletrocardiograma e teste ergométrico. Retorno com exames.','AAS 100mg 1x/dia. Anlodipino 5mg 1x/dia.','DfHFQ17NJs5BozqZqO59rubfAsCZsNpUb+5vlVpgfWlVjoeEcRV445AdYyB/T/X+6Xo4KPKX8NAqxU4UwJLlQNUkuS4=','ECG de repouso, Teste ergométrico, Perfil lipídico','30 dias','2026-10-08 19:26:19'),(2,4,10,18,'Manchas na pele','Paciente apresenta manchas eritematosas em braços há 2 meses.','Lesões maculopapulares em face extensora de antebraços bilateralmente.','120/80',72,36.2,99,58.00,165,'Dermatite de contato','JaPZOOkn5gtwJ6cn0MxdQePafWB2K1TyYZQAp88MlFtVwmMZDDrjPdsf38K592Kv','L23.9','Orientado evitar contato com agentes irritantes. Prescrito corticoide tópico.','Hidrocortisona creme 1% 2x/dia por 10 dias','w5QYwV5eYUTZeztNNijwaz3YW5mGBU/v+jKrh9ME4NCvgTFNQpu2/ReUCtDZWvKm2+N4kxBqVUcVPihzZjtflQtCxZOJ/Q==',NULL,'15 dias','2026-10-08 19:26:19');
